/**
 * The default roster, as data.
 *
 * `roster-default.json` next to this file is the shipped table: which models
 * Milo picks when nobody has configured a roster, what each one costs, how
 * much traffic each one actually carries, and where the numbers came from. It
 * is generated by `packages/evals/scripts/roster-refresh.ts`, which reads
 * OpenRouter's weekly usage ranking and its price catalogue and applies the
 * band rules, so the table can be re-derived rather than argued about. A
 * scheduled job refreshes it weekly (`.github/workflows/roster-refresh.yml`).
 *
 * `DEFAULT_ROSTER` is the ids alone, in the shape the router and the config
 * file already use (`Roster`). `DEFAULT_ROSTER_INFO` is the whole record --
 * prices, usage ranks, weekly tokens, band rules, provenance -- for the
 * surfaces that disclose the default to a user (`GET /v1/roster`, `GET /`,
 * `milo roster`).
 *
 * ## Why these models
 *
 * Milo is built for a frontier agent that plans on a subscription model
 * (Opus, Fable, Sol) and hands its implementation sub-tasks to Milo. Those
 * sub-tasks are the volume, and volume is exactly what people use OpenRouter
 * for: cheap, popular models, not a second copy of the frontier model they
 * already pay for. So the default roster is the ten models that carry the
 * most tokens in OpenRouter's programming category, tiered by output price,
 * with a hard ceiling (`excludedAbove`) above which nothing is ever chosen by
 * default. A user who wants a premium model asks for it: per request with
 * `milo.candidates`, or per deployment with `roster` in `milo.config.json`.
 */

import rosterJson from "./roster-default.json" with { type: "json" };
import type { Roster, Tier } from "../types.js";

/** One model in the default roster, with the numbers that put it there. */
export type RosterModel = {
  /** OpenRouter model id. */
  id: string;
  inputUsdPerM: number;
  outputUsdPerM: number;
  /**
   * Position in OpenRouter's weekly usage ranking for the programming
   * category, counted over the models that survive the eligibility rules.
   */
  usageRank: number;
  /** Tokens served through OpenRouter in the ranking week. */
  weeklyTokens: number;
  contextLength: number;
  /**
   * Max output tokens, when the provider caps it below the context window.
   * Absent means "large enough for anything the router will ask for".
   */
  maxOutputTokens?: number;
  /**
   * Set when `maxOutputTokens` is below `smallOutputBelowTokens`. Such a model
   * is skipped outright on a long-output request, so it must never be a tier
   * default: it sorts last within its tier.
   */
  demotedForSmallOutput?: boolean;
};

export type RosterBand = { maxOutputUsdPerM: number };

/** The whole shipped table, provenance included. */
export type RosterInfo = {
  /** The date the prices and the ranking were collected, `YYYY-MM-DD`. */
  version: string;
  source: { usage: string; pricing: string };
  /** How many models the ranking contributes, before tiering. */
  topModels: number;
  /** Output price ceiling per tier, USD per million tokens. */
  bands: Record<Tier, RosterBand>;
  /** Output price at or above which a model is never a default, USD per million. */
  excludedAbove: number;
  /** A model whose max output is below this cannot be a tier default. */
  smallOutputBelowTokens: number;
  tiers: Record<Tier, RosterModel[]>;
};

export const DEFAULT_ROSTER_INFO: RosterInfo = rosterJson as RosterInfo;

const TIER_KEYS = ["fast", "mid", "frontier"] as const satisfies readonly Tier[];

/**
 * `long_output` at or above `LONG_OUTPUT_THRESHOLD` skips any model whose max
 * output is below this. Read from the JSON so the rule and the data that feeds
 * it cannot drift: the refresh script writes both.
 */
export const SMALL_OUTPUT_BELOW_TOKENS = DEFAULT_ROSTER_INFO.smallOutputBelowTokens;

/** True when this model cannot hold a long answer. */
export function isSmallOutput(model: RosterModel, belowTokens = SMALL_OUTPUT_BELOW_TOKENS): boolean {
  return model.maxOutputTokens !== undefined && model.maxOutputTokens < belowTokens;
}

/** The ids alone, per tier, in the JSON's order. This is what the router routes on. */
export const DEFAULT_ROSTER: Roster = Object.freeze(
  Object.fromEntries(TIER_KEYS.map((tier) => [tier, DEFAULT_ROSTER_INFO.tiers[tier].map((m) => m.id)])),
) as Roster;

/**
 * Default-roster models the long-output rule skips, derived from the JSON's
 * own `maxOutputTokens` rather than maintained by hand. Adding a short-output
 * model to the data excludes it here automatically.
 */
export const DEFAULT_SMALL_OUTPUT_MODELS: string[] = TIER_KEYS.flatMap((tier) =>
  DEFAULT_ROSTER_INFO.tiers[tier].filter((m) => isSmallOutput(m)).map((m) => m.id),
);

/**
 * The one-line disclosure every surface prints: the root page, `/v1/roster`,
 * `/setup.md`, the skill, and `milo roster`. One string so they cannot drift.
 */
export const ROSTER_NOTE =
  "Defaults are the models people actually run on OpenRouter, ordered by weekly usage within " +
  `price bands; nothing above $${DEFAULT_ROSTER_INFO.excludedAbove} per million output tokens is ` +
  "chosen unless you list it in `candidates` or your roster config.";

/** How to get a model the default roster will never pick on its own. */
export const ROSTER_OVERRIDE_NOTE =
  "Premium models (Fable, Opus, Astra, Sonnet) are one line away: list their OpenRouter ids per " +
  "request in `milo.candidates`, or per deployment under `roster` in `milo.config.json`.";

/** Which tier each cost posture leans toward, for the disclosure surfaces. */
export const ROSTER_POSTURE_POLICY: Record<"low" | "balanced" | "quality", string> = {
  low: "favors fast and never returns frontier, whatever the difficulty says",
  balanced: "fast for easy work, mid by default, frontier once the difficulty mass clears the bar",
  quality: "reaches frontier as soon as the work looks substantial",
};

/** Every default-roster record, flattened, with its tier. */
export function defaultRosterModels(): Array<RosterModel & { tier: Tier }> {
  return TIER_KEYS.flatMap((tier) => DEFAULT_ROSTER_INFO.tiers[tier].map((m) => ({ ...m, tier })));
}

/** The default record for one model id, or `undefined` if it is not a default. */
export function defaultRosterModel(id: string): (RosterModel & { tier: Tier }) | undefined {
  return defaultRosterModels().find((m) => m.id === id);
}
